const Fastify = require('fastify');
const fp = require('fastify-plugin');
const { db } = require('./db');
const { verifyJwt } = require('./auth');

const fastify = Fastify({ logger: false });

// Encapsulate workspace authorization within a scoped plugin rather than global fastify-plugin
fastify.register(async function workspaceRoutes(app) {
  app.addHook('preHandler', async (request, reply) => {
    const user = await verifyJwt(request.headers.authorization);
    if (!user) {
      return reply.status(401).send({ error: 'Unauthorized' });
    }
    request.user = user;

    if (request.params && request.params.workspaceId) {
      const workspace = await db.workspaces.findById(request.params.workspaceId);
      if (!workspace) {
        return reply.status(404).send({ error: 'Workspace not found' });
      }

      // Verify that user is an authorized member of the target workspace
      const membership = await db.workspaceMembers.findOne({
        where: { workspaceId: workspace.id, userId: user.id }
      });

      if (!membership) {
        return reply.status(403).send({ error: 'Access denied: not a member of this workspace' });
      }

      request.currentWorkspace = workspace;
    }
  });

  app.get('/api/workspaces/:workspaceId/secrets', async (request, reply) => {
    const secrets = await db.secrets.findAll({ where: { workspaceId: request.currentWorkspace.id } });
    return reply.send({ workspaceId: request.currentWorkspace.id, secrets });
  });
});

fastify.listen({ port: 8091 });
